import csv
from collections import defaultdict
from decimal import Decimal, InvalidOperation
totals = defaultdict(Decimal)
bad = []
with open('/work/invoices.csv', newline='') as f:
    for r in csv.DictReader(f):
        cust = (r['customer'] or '').strip()
        try:
            amt = Decimal(r['amount'].strip().replace(',','').replace('$',''))
        except (InvalidOperation, AttributeError):
            bad.append(r); continue
        totals[cust] += amt
for r in bad: print("UNPARSEABLE:", r)
ranked = sorted(totals.items(), key=lambda x: x[1], reverse=True)
for c, t in ranked: print(f"{c}: {t:.2f}")
print("GRAND TOTAL:", f"{sum(totals.values()):.2f}")
print("TOP 3:")
for i,(c,t) in enumerate(ranked[:3],1): print(i, c, f"{t:.2f}")

